ZTEST(mcuboot_interface, test_read_bank_header_size_offbyone)
{
	struct mcuboot_img_header header;
	size_t v1_min_size = sizeof(uint32_t) + sizeof(struct mcuboot_img_header_v1);
	int ret;
	const struct flash_area *fa;
	const uint32_t magic = BOOT_MAGIC_GOOD;

	ret = flash_area_open(SLOT0_PARTITION_ID, &fa);
	zassert_true(ret == 0, "flash_area_open failed");

	/* Write magic to ensure v1 header path is taken. */
	ret = flash_area_erase(fa, 0, fa->fa_size);
	zassert_true(ret == 0, "flash_area_erase failed");
	ret = flash_area_write(fa, 0, &magic, sizeof(magic));
	zassert_true(ret == 0, "flash_area_write failed");

	flash_area_close(fa);

	ret = boot_read_bank_header(SLOT0_PARTITION_ID, &header, v1_min_size - 1);
	zassert_equal(ret, -ENOMEM,
		      "expected -ENOMEM for header_size one byte too small, got %d", ret);
}
